const MOD = 1000000007n;

const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
const n = parseInt(input[0]);
const m = parseInt(input[1]);
const k = parseInt(input[2]);

const MAX = 2020;
const dp = Array.from({ length: MAX }, () => Array(MAX).fill(0n));

const maxNM = Math.max(n, m);

for (let i = 0; i < maxNM; i++) {
