        if (j === 0) {
            dp[j][i] = 1n;
        } else {
            dp[j][i] = (dp[j][i - 1] + dp[j - 1][i - 1]) % MOD;
        }
    }
}

const row = 2 * k;
const res = (dp[row][n - 1] * dp[row][m - 1]) % MOD;
console.log(res.toString());

